{
        VipsForeignLoadJpeg *jpeg = (VipsForeignLoadJpeg *) object;
        VipsForeignLoadJpegFile *file = (VipsForeignLoadJpegFile *) object;

        if( file->filename &&
                !(jpeg->source =
                        vips_source_new_from_file( file->filename )) )
